.darma-loader-fidget-spinner {
  position: relative;
  width: 52px;
  height: 52px;
  animation: darma-loader-fidget-spinner-spin 0.9s ease-in-out infinite;
}
.darma-loader-fidget-spinner::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border-radius: 50%;
  border: 3px solid var(--loader-color, #6366f1);
  box-sizing: border-box;
  background: #e0e7ff;
  z-index: 2;
}
.darma-loader-fidget-spinner i {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 16px;
  height: 16px;
  margin: -8px 0 0 -8px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
}
.darma-loader-fidget-spinner i:nth-child(1) { transform: rotate(0deg) translateY(-17px); }
.darma-loader-fidget-spinner i:nth-child(2) { transform: rotate(120deg) translateY(-17px); }
.darma-loader-fidget-spinner i:nth-child(3) { transform: rotate(240deg) translateY(-17px); }
@keyframes darma-loader-fidget-spinner-spin { to { transform: rotate(360deg); } }

